Here's a complete Mario Kart-inspired racing game in three files:

## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Mario Kart Web Edition</title>
    <link rel="stylesheet" href="style.css">
</head>
<body>
    <div id="menu-screen">
        <h1>🏁 Mario Kart Web Edition</h1>
        <p>Select your character:</p>
        <div class="char-grid">
            <button class="char-btn" data-char="mario" onclick="startGame('mario')">
                <span>🔴</span> Mario
            </button>
            <button class="char-btn" data-char="luigi" onclick="startGame('luigi')">
                <span>🟢</span> Luigi
            </button>
            <button class="char-btn" data-char="peach" onclick="startGame('peach')">
                <span>🟠</span> Peach
            </button>
            <button class="char-btn" data-char="toshy" onclick="startGame('toshy')">
                <span>🟡</span> Yoshi
            </button>
            <button class="char-btn" data-char="wario" onclick="startGame('wario')">
                <span>⚫</span> Wario
            </button>
        </div>
        <p style="color: #666; margin-top: 20px;">Controls: Arrow Keys / WASD | Space = Use Item</p>
    </div>

    <div id="game-screen" style="display:none;">
        <canvas id="gameCanvas"></canvas>
        <div id="hud">
            <div id="lap-info">Lap: 1 / 3</div>
            <div id="position-info">Position: 1st</div>
            <div id="item-info">No item</div>
            <div id="speed-info">Speed: 0</div>
        </div>
        <div id="pause-overlay">
            <button onclick="backToMenu()">Back to Menu</button>
        </div>
    </div>

    <script src="game.js"></script>
</body>
</html>
```

## `style.css`

```css
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    background: #1a1a2e;
    font-family: 'Segoe UI', Tahoma, Geneva, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    color: white;
}

#menu-screen {
    text-align: center;
    max-width: 600px;
}

#menu-screen h1 {
    font-size: 3rem;
    margin-bottom: 10px;
    color: #ff4444;
    text-shadow: 0 0 20px rgba(255,68,68,0.5);
}

.char-grid {
    display: flex;
    gap: 15px;
    justify-content: center;
    margin-top: 30px;
    flex-wrap: wrap;
}

.char-btn {
    padding: 20px 30px;
    border: none;
    border-radius: 12px;
    font-size: 1.2rem;
    cursor: pointer;
    background: #fff;
    color: #333;
    transition: all 0.2s;
    box-shadow: 0 4px 15px rgba(0,0,0,0.3);
}

.char-btn:hover {
    transform: scale(1.1);
    box-shadow: 0 6px 20px rgba(0,0,0,0.4);
}

#game-screen {
    display: none;
    max-width: 800px;
    width: 100%;
}

canvas {
    width: 100%;
    border-radius: 12px;
    background: #2d2d4a;
    box-shadow: 0 8px 30px rgba(0,0,0,0.5);
}

#hud {
    display: flex;
    justify-content: space-between;
    margin-top: 15px;
    padding: 10px;
    background: rgba(255,255,255,0.1);
    border-radius: 8px;
}

#hud div {
    font-size: 1rem;
    font-weight: bold;
}

#pause-overlay button {
    padding: 15px 30px;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    cursor: pointer;
    background: #ff4444;
    color: white;
    margin-top: 20px;
}

#pause-overlay button:hover {
    background: #cc3333;
}

/* Character colors */
.char-btn[data-char="mario"] { background: #ff5555; color: white; }
.char-btn[data-char="luigi"] { background: #44bb44; color: white; }
.char-btn[data-char="peach"] { background: #ff9966; color: white; }
.char-btn[data-char="toshy"] { background: #55aa55; color: white; }
.char-btn[data-char="wario"] { background: #444444; color: white; }
```

## `game.js`

```javascript
// === GAME CONFIGURATION ===
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const TRACK_WIDTH = 120;
const TOTAL_LAPS = 3;

// Character stats
const CHARACTERS = {
    mario:   { color: '#ff4444', maxSpeed: 8, accel: 0.15, handling: 0.9 },
    luigi:   { color: '#44bb44', maxSpeed: 7, accel: 0.2, handling: 0.85 },
    peach:   { color: '#ff9966', maxSpeed: 7, accel: 0.15, handling: 1.1 },
    toshy:   { color: '#55aa55', maxSpeed: 9, accel: 0.25, handling: 0.8 },
    wario:   { color: '#333333', maxSpeed: 6, accel: 0.2, handling: 1.0 }
};

// Track waypoints (clockwise around the track)
const TRACK_POINTS = [
    {x: 400, y: 80},   // start line top
    {x: 700, y: 150},
    {x: 700, y: 350},
    {x: 550, y: 450},
    {x: 250, y: 450},
    {x: 100, y: 350},
    {x: 100, y: 150},
    {x: 250, y: 80}
];

// Item positions on track (indices into TRACK_POINTS)
const ITEM_SPAWN_LOCATIONS = [2, 4, 6];

// === GAME STATE ===
let canvas, ctx;
let playerChar;
let players = []; // AI opponents
let playerState;
let gameRunning = false;
let raceFinished = false;
let currentLap = 1;
let totalPlayers = 5;

let obstacles = []; // Shells & bananas on track
let itemSpawnTimer = 0;

// === INITIALIZATION ===
function initCanvas() {
    canvas = document.getElementById('gameCanvas');
    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;
    ctx = canvas.getContext('2d');
}

function startGame(charName) {
    playerChar = charName;
    initCanvas();

    // Create player
    const stats = CHARACTERS[playerChar];
    playerState = {
        x: TRACK_POINTS[0].x,
        y: TRACK_POINTS[0].y,
        angle: 0,
        speed: 0,
        charName: playerChar,
        color: stats.color,
        maxSpeed: stats.maxSpeed,
        accel: stats.accel,
        handling: stats.handling,
        item: null,
        boosted: false,
        boostTimer: 0,
        lapIndex: 0,
        finishedLaps: 0
    };

    // Create AI opponents
    const chars = ['luigi', 'peach', 'toshy', 'wario'].filter(c => c !== playerChar);
    // If only 1 char selected, add some duplicates
    while (chars.length < totalPlayers - 1) {
        chars.push(chars[Math.floor(Math.random() * chars.length)]);
    }

    players = [];
    for (let i = 0; i < totalPlayers - 1; i++) {
        const cName = chars[i];
        const stats = CHARACTERS[cName];
        players.push({
            x: TRACK_POINTS[0].x + (i + 1) * 20,
            y: TRACK_POINTS[0].y,
            angle: 0,
            speed: 0,
            charName: cName,
            color: stats.color,
            maxSpeed: stats.maxSpeed,
            accel: stats.accel,
            handling: stats.handling,
            item: null,
            boosted: false,
            boostTimer: 0,
            lapIndex: 0,
            finishedLaps: 0,
            aiTimer: Math.random() * 200, // stagger AI decisions
            targetPoint: 1 // which track point to aim for
        });
    }

    document.getElementById('menu-screen').style.display = 'none';
    document.getElementById('game-screen').style.display = 'block';

    gameRunning = true;
    currentLap = 1;

    setupControls();
    gameLoop();
}

function backToMenu() {
    gameRunning = false;
    raceFinished = false;
    document.getElementById('menu-screen').style.display = 'block';
    document.getElementById('game-screen').style.display = 'none';
}

// === CONTROLS ===
let keys = {};

function setupControls() {
    window.addEventListener('keydown', (e) => {
        keys[e.key] = true;
        if (e.key === ' ') useItem();
    });
    window.addEventListener('keyup', (e) => {
        keys[e.key] = false;
    });
}

function useItem() {
    if (!playerState.item || !gameRunning) return;

    const item = playerState.item;
    if (item.type === 'mushroom') {
        playerState.boosted = true;
        playerState.boostTimer = 150; // frames (~2.5s)
        playerState.speed = Math.min(playerState.speed + 4, playerState.maxSpeed * 1.5);
    } else if (item.type === 'shell') {
        obstacles.push({
            x: playerState.x,
            y: playerState.y,
            type: 'shell',
            angle: playerState.angle,
            speed: 8,
            frames: 60,
            color: '#ff3333'
        });
    } else if (item.type === 'banana') {
        obstacles.push({
            x: playerState.x,
            y: playerState.y,
            type: 'banana',
            angle: 0,
            frames: 120,
            color: '#ffcc00'
        });
    }

    playerState.item = null;
}

// === TRACK HELPERS ===
function getTrackCenter(i) {
    return TRACK_POINTS[i % TRACK_POINTS.length];
}

function distToTrackPoint(x, y, pointIdx) {
    const p = TRACK_POINTS[pointIdx % TRACK_POINTS.length];
    return Math.sqrt((x - p.x) ** 2 + (y - p.y) ** 2);
}

function getDirectionToNext(x, y, nextIdx) {
    const p = TRACK_POINTS[nextIdx % TRACK_POINTS.length];
    return Math.atan2(p.y - y, p.x - x);
}

// === MOVEMENT ===
function movePlayer(state) {
    const nextIdx = (state.lapIndex + 1) % TRACK_POINTS.length;
    const target = getDirectionToNext(state.x, state.y, nextIdx);

    if (state.boosted && state.boostTimer > 0) {
        state.speed = Math.min(state.speed + 0.3, state.maxSpeed * 1.5);
        state.boostTimer--;
        if (state.boostTimer <= 0) state.boosted = false;
    }

    // Player controls
    let accelInput = 0;
    let steerInput = 0;

    if (keys['ArrowUp'] || keys['w']) accelInput = 1;
    if (keys['ArrowDown'] || keys['s']) accelInput = -1;
    if (keys['ArrowLeft'] || keys['a']) steerInput = -1;
    if (keys['ArrowRight'] || keys['d']) steerInput = 1;

    // Apply acceleration
    if (accelInput > 0) {
        state.speed += state.accel;
    } else if (accelInput < 0) {
        state.speed -= state.accel * 1.5;
    }

    state.speed = Math.max(0, Math.min(state.speed, state.maxSpeed));

    // Steering - drift mechanics
    if (steerInput !== 0) {
        state.angle += steerInput * state.handling * 0.05;
    }

    // Keep angle within 0-2PI
    state.angle = ((state.angle % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);

    // Move
    state.x += Math.cos(state.angle) * state.speed;
    state.y += Math.sin(state.angle) * state.speed;

    // Clamp to canvas
    state.x = Math.max(20, Math.min(CANVAS_WIDTH - 20, state.x));
    state.y = Math.max(20, Math.min(CANVAS_HEIGHT - 20, state.y));
}

function moveAI(player) {
    const nextIdx = (player.lapIndex + 1) % TRACK_POINTS.length;

    // AI gradually adjusts target point
    if (player.aiTimer <= 0) {
        player.targetPoint = nextIdx;
        player.aiTimer = Math.random() * 150 + 50;
    } else {
        player.aiTimer--;
    }

    const angleToTarget = getDirectionToNext(player.x, player.y, player.targetPoint);
    const currentAngle = player.angle;

    // Smooth steering toward target
    let angleDiff = angleToTarget - currentAngle;
    while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
    while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

    player.angle += Math.sign(angleDiff) * Math.min(Math.abs(angleDiff), 0.15) * player.handling;

    // Accelerate mostly
    player.speed += player.accel;
    if (player.boosted && player.boostTimer > 0) {
        player.speed = Math.min(player.speed + 0.3, player.maxSpeed * 1.5);
        player.boostTimer--;
        if (player.boostTimer <= 0) player.boosted = false;
    }

    // Occasional AI boost
    if (Math.random() < 0.02 && !player.boosted) {
        player.boosted = true;
        player.boostTimer = 100 + Math.random() * 50;
        player.speed = Math.min(player.speed + 3, player.maxSpeed * 1.5);
    }

    // Occasional AI item use
    if (player.item && Math.random() < 0.05) {
        const item = player.item;
        if (item.type === 'mushroom') {
            player.boosted = true;
            player.boostTimer = 150;
            player.speed = Math.min(player.speed + 4, player.maxSpeed * 1.5);
            player.item = null;
        } else if (item.type === 'shell') {
            obstacles.push({
                x: player.x, y: player.y, type: 'shell', angle: player.angle,
                speed: 8, frames: 60, color: '#ff3333'
            });
            player.item = null;
        } else if (item.type === 'banana') {
            obstacles.push({
                x: player.x, y: player.y, type: 'banana', angle: 0, frames: 120, color: '#ffcc00'
            });
            player.item = null;
        }
    }

    player.angle = ((player.angle % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
    player.x += Math.cos(player.angle) * player.speed;
    player.y += Math.sin(player.angle) * player.speed;
    player.x = Math.max(20, Math.min(CANVAS_WIDTH - 20, player.x));
    player.y = Math.max(20, Math.min(CANVAS_HEIGHT - 20, player.y));
}

// === LAP TRACKING ===
function checkLap(state) {
    const nextIdx = (state.lapIndex + 1) % TRACK_POINTS.length;
    const dist = distToTrackPoint(state.x, state.y, nextIdx);

    if (dist < 40) {
        state.lapIndex = nextIdx;
        if (state.lapIndex === 0) {
            state.finishedLaps++;
            currentLap++;
            if (state.finishedLaps >= TOTAL_LAPS && state === playerState) {
                raceFinished = true;
                gameRunning = false;
                drawFinishLine();
            }
        }
    }
}

// === COLLISION ===
function checkCollisions(state) {
    // Check obstacles
    for (let obs of obstacles) {
        const dist = Math.sqrt((state.x - obs.x) ** 2 + (state.y - obs.y) ** 2);
        if (dist < 25) {
            if (obs.type === 'shell') {
                // Hit shell - slow down and bounce
                state.speed *= 0.3;
                state.angle += Math.PI;
                // Remove obstacle after some time
                obs.frames = 0;
            } else if (obs.type === 'banana') {
                state.speed *= 0.5;
                state.angle += Math.PI * 0.5;
                obs.frames -= 20; // last longer for player
            }
        }
    }

    // Remove expired obstacles
    obstacles = obstacles.filter(o => o.frames > 0);
}

// === ITEM SPAWNING ===
function spawnItems() {
    itemSpawnTimer++;
    if (itemSpawnTimer % 60 === 0) {
        const locIdx = ITEM_SPAWN_LOCATIONS[Math.floor(Math.random() * ITEM_SPAWN_LOCATIONS.length)];
        const p = TRACK_POINTS[locIdx];

        // Check if there's already an item there
        const existing = obstacles.filter(o => distToTrackPoint(o.x, o.y, locIdx) < 50);
        if (existing.length === 0) {
            const types = ['mushroom', 'shell', 'banana'];
            const type = types[Math.floor(Math.random() * types.length)];

            // Give to a random player
            const allPlayers = [playerState, ...players];
            const recipient = allPlayers[Math.floor(Math.random() * allPlayers.length)];
            if (!recipient.item) {
                recipient.item = { type };
            }
        }
    }
}

// === RENDERING ===
function drawTrack() {
    ctx.fillStyle = '#2d2d4a';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw track path
    ctx.strokeStyle = '#555577';
    ctx.lineWidth = TRACK_WIDTH;
    ctx.lineCap = 'round';

    ctx.beginPath();
    for (let i = 0; i < TRACK_POINTS.length; i++) {
        const p1 = TRACK_POINTS[i % TRACK_POINTS.length];
        const p2 = TRACK_POINTS[(i + 1) % TRACK_POINTS.length];
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
    }
    ctx.stroke();

    // Track border lines
    ctx.strokeStyle = '#888';
    ctx.lineWidth = 3;
    for (let i = 0; i < TRACK_POINTS.length; i++) {
        const p1 = TRACK_POINTS[i % TRACK_POINTS.length];
        const p2 = TRACK_POINTS[(i + 1) % TRACK_POINTS.length];

        // Calculate perpendicular offset
        const dx = p2.x - p1.x;
        const dy = p2.y - p1.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const nx = -dy / len * (TRACK_WIDTH / 2);
        const ny = dx / len * (TRACK_WIDTH / 2);

        ctx.moveTo(p1.x + nx, p1.y + ny);
        ctx.lineTo(p2.x + nx, p2.y + ny);

        ctx.moveTo(p1.x - nx, p1.y - ny);
        ctx.lineTo(p2.x - nx, p2.y - ny);
    }
    ctx.stroke();

    // Draw checkpoint line (start/finish)
    const start = TRACK_POINTS[0];
    const next = TRACK_POINTS[1];
    const dx = next.x - start.x;
    const dy = next.y - start.y;
    const len = Math.sqrt(dx * dx + dy * dy);
    const nx = -dy / len;
    const ny = dx / len;

    ctx.strokeStyle = '#ffcc00';
    ctx.lineWidth = 8;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(start.x + nx * 30, start.y + ny * 30);
    ctx.lineTo(start.x - nx * 30, start.y - ny * 30);
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw checkpoints at each track point
    for (let i = 1; i < TRACK_POINTS.length; i++) {
        const p = TRACK_POINTS[i];
        const next = TRACK_POINTS[(i + 1) % TRACK_POINTS.length];
        const dx = next.x - p.x;
        const dy = next.y - p.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const nx = -dy / len;
        const ny = dx / len;

        ctx.fillStyle = '#aaa';
        ctx.beginPath();
        ctx.arc(p.x, p.y, 8, 0, Math.PI * 2);
        ctx.fill();
    }
}

function drawObstacles() {
    for (let obs of obstacles) {
        if (obs.frames <= 0) continue;
        const alpha = obs.frames / 120;

        if (obs.type === 'shell') {
            ctx.fillStyle = '#ff3333';
            ctx.save();
            ctx.translate(obs.x, obs.y);
            ctx.rotate(obs.angle);
            // Draw shell shape
            ctx.beginPath();
            ctx.arc(0, 0, 15, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.arc(0, 0, 8, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        } else if (obs.type === 'banana') {
            ctx.fillStyle = '#ffcc00';
            ctx.save();
            ctx.translate(obs.x, obs.y);
            ctx.beginPath();
            ctx.arc(0, 0, 12, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }
    }
}

function drawKart(x, y, angle, color, charName) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    // Kart body
    ctx.fillStyle = '#333';
    ctx.fillRect(-15, -8, 30, 16);

    // Character
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();

    // Wheels
    ctx.fillStyle = '#555';
    ctx.fillRect(-18, -12, 6, 4);
    ctx.fillRect(-18, 8, 6, 4);
    ctx.fillRect(12, -12, 6, 4);
    ctx.fillRect(12, 8, 6, 4);

    // Boost effect
    ctx.restore();
}

function drawItem(item) {
    if (!item) return;
    const x = playerState.x + Math.cos(playerState.angle) * 25;
    const y = playerState.y + Math.sin(playerState.angle) * 25;

    ctx.save();
    ctx.translate(x, y);

    if (item.type === 'mushroom') {
        ctx.fillStyle = '#ff4444';
        ctx.beginPath();
        ctx.arc(0, 0, 10, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.fillRect(-3, -5, 6, 3);
    } else if (item.type === 'shell') {
        ctx.fillStyle = '#ff3333';
        ctx.beginPath();
        ctx.arc(0, 0, 10, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(0, 0, 5, 0, Math.PI * 2);
        ctx.fill();
    } else if (item.type === 'banana') {
        ctx.fillStyle = '#ffcc00';
        ctx.beginPath();
        ctx.arc(0, 0, 10, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

function drawFinishLine() {
    const overlay = document.getElementById('pause-overlay');
    overlay.style.display = 'block';

    // Calculate player position
    const posRank = calculatePosition();
    let msg = raceFinished ? `🏆 You finished ${posRank}!` : 'Race ended!';
    overlay.querySelector('button').textContent = `${msg} - Back to Menu`;
}

function calculatePosition() {
    const allP = [playerState, ...players];
    allP.sort((a, b) => {
        if (b.finishedLaps !== a.finishedLaps) return b.finishedLaps - a.finishedLaps;
        return distToTrackPoint(a.x, a.y, 0) - distToTrackPoint(b.x, b.y, 0);
    });

    const idx = allP.findIndex(p => p === playerState);
    return idx + 1;
}

// === HUD ===
function updateHUD() {
    document.getElementById('lap-info').textContent = `Lap: ${currentLap} / ${TOTAL_LAPS}`;
    document.getElementById('position-info').textContent = `Position: ${calculatePosition()}${['st', 'nd', 'rd'][calculatePosition() - 1] || 'th'}`;

    const itemStr = playerState.item ? playerState.item.type + (playerState.boosted ? ' (boosted!)' : '') : 'No item';
    document.getElementById('item-info').textContent = `Item: ${itemStr}`;
    document.getElementById('speed-info').textContent = `Speed: ${Math.round(playerState.speed * 10)} km/h`;
}

// === GAME LOOP ===
function gameLoop() {
    if (!gameRunning) return;

    // Update player
    movePlayer(playerState);
    checkLap(playerState);
    checkCollisions(playerState);

    // Update AI
    for (let p of players) {
        moveAI(p);
        checkLap(p);
        checkCollisions(p);
    }

    // Spawn items
    spawnItems();

    // Draw
    drawTrack();
    drawObstacles();

    // Draw player kart + item indicator
    drawKart(playerState.x, playerState.y, playerState.angle, playerState.color, playerState.charName);
    if (playerState.item && !playerState.boosted) {
        drawItem(playerState.item);
    }

    // Draw AI karts
    for (let p of players) {
        drawKart(p.x, p.y, p.angle, p.color, p.charName);
        if (p.item && !p.boosted) {
            drawItem(p.item);
        }
    }

    updateHUD();

    requestAnimationFrame(gameLoop);
}
```

---

### How to Play:

1. **Open** `index.html` in a browser
2. **Select** your character from the menu
3. **Controls:**
   - **Arrow Keys / WASD**: Steer & accelerate (Up=accelerate, Down=brake, Left/Right=steer)
   - **Spacebar**: Use collected item (Mushroom = speed boost, Shell = throws obstacle, Banana = drops trap)

### Features:
- 🛣️ **Rounded track** with checkpoints
