    gameState.playerKart.draw(ctx);
    gameState.aiKarts.forEach(ai => ai.draw(ctx));

    drawProjectiles(ctx);
    drawParticles(ctx);
    drawMinimap();

    requestAnimationFrame(gameLoop);
}

// ========== KEY HANDLING ==========
const keys = { up: false, down: false, left: false, right: false, space: false };

document.addEventListener('keydown', (e) => {
    switch(e.key) {
