```javascript
// ============================
// MARIO KART WEB EDITION
// ============================

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const miniCanvas = document.getElementById('minimap');
const miniCtx = miniCanvas.getContext('2d');

// ========== CONSTANTS ==========
const TRACK_POINTS = [
    { x: 400, y: 50 },   // top center
    { x: 600, y: 100 },  // top right
    { x: 700, y: 250 },  // far right
    { x: 650, y: 400 },  // bottom right
    { x: 400, y: 550 },  // bottom center
    { x: 150, y: 400 },  // bottom left
    { x: 100, y: 250 },  // far left
    { x: 200, y: 100 },  // top left
];

const TOTAL_LAPS = 3;
const TRACK_WIDTH = 60;
const PLAYER_SIZE = 20;
const AI_SIZE = 18;
const MAX_SPEED = 5;
const ACCELERATION = 0.05;
const TURN_RATE = 0.04;

// ========== ITEM TYPES ==========
const ITEMS = {
    banana: { color: '#fdd', icon: '🍌', effect: 'spin' },
    shell: { color: '#c6c', icon: '🛑', effect: 'forward' },
    mushroom: { color: '#e22', icon: '🍄', effect: 'boost' },
    star: { color: '#ffd700', icon: '⭐', effect: 'invincible' }
};

// ========== GAME STATE ==========
let gameState = {
    playerKart: null,
    aiKarts: [],
    itemsOnTrack: [],
    projectiles: [],
    particles: [],
    currentLap: 0,
    gameStarted: false,
    finished: false,
    raceTime: 0,
    trackSegments: [],
    itemPositions: []
};

// ========== KART CLASS ==========
class Kart {
    constructor(id, color, name) {
        this.id = id;
        this.color = color;
        this.name = name;
        this.trackIndex = 0;
        this.speed = 0;
        this.position = { x: TRACK_POINTS[0].x, y: TRACK_POINTS[0].y };
        this.angle = Math.atan2(TRACK_POINTS[1].y - TRACK_POINTS[0].y, TRACK_POINTS[1].x - TRACK_POINTS[0].x);
        this.lap = 0;
        this.items = [];
        this.spinTimer = 0;
        this.boostTimer = 0;
        this.invincibleTimer = 0;
        this.hitRadius = 30;
    }

    getPointOnTrack(index) {
        const n = TRACK_POINTS.length;
        const segIdx = ((index % n) + n) % n;
        const nextIdx = (segIdx + 1) % n;
        const frac = index - Math.floor(index);
        const p0 = TRACK_POINTS[segIdx];
        const p1 = TRACK_POINTS[nextIdx];
        return {
            x: p0.x + (p1.x - p0.x) * frac,
            y: p0.y + (p1.y - p0.y) * frac
        };
    }

    moveForwards() {
        if (this.spinTimer > 0) {
            this.angle += 0.2;
            this.position = this.getPointOnTrack(this.trackIndex);
            this.spinTimer--;
            return;
        }

        const speed = this.boostTimer > 0 ? MAX_SPEED * 1.5 : Math.min(this.speed, MAX_SPEED);
        if (this.boostTimer > 0) this.boostTimer--;
        if (this.invincibleTimer > 0) this.invincibleTimer--;

        this.trackIndex += speed / 2;
        const currentPoint = this.getPointOnTrack(this.trackIndex);
        this.position.x = currentPoint.x;
        this.position.y = currentPoint.y;

        // Calculate angle toward next point
        const nextIdx = Math.floor(this.trackIndex) + 1;
        const nextPoint = this.getPointOnTrack(nextIdx);
        const dx = nextPoint.x - currentPoint.x;
        const dy = nextPoint.y - currentPoint.y;
        if (dx !== 0 || dy !== 0) {
            this.angle = Math.atan2(dy, dx);
        }

        // Lap tracking
        const n = TRACK_POINTS.length;
        if (this.trackIndex >= n * 2) {
            this.lap++;
            this.trackIndex -= n;
        }
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.position.x, this.position.y);
        ctx.rotate(this.angle);

        // Spin effect
        if (this.spinTimer > 0) {
            ctx.rotate(Date.now() / 100);
        }

        // Invincible glow
        if (this.invincibleTimer > 0) {
            ctx.strokeStyle = '#ffd700';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(0, 0, PLAYER_SIZE + 5, 0, Math.PI * 2);
            ctx.stroke();
        }

        // Boost trail
        if (this.boostTimer > 0) {
            ctx.strokeStyle = '#ff6600';
            ctx.lineWidth = 2;
            for (let i = 1; i <= 3; i++) {
                ctx.beginPath();
                ctx.arc(-i * 5, 0, 3, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        // Kart body
        ctx.fillStyle = this.color;
        ctx.fillRect(-PLAYER_SIZE, -PLAYER_SIZE / 2, PLAYER_SIZE, PLAYER_SIZE);

        // Wheels
        ctx.fillStyle = '#333';
        ctx.fillRect(-PLAYER_SIZE - 5, -PLAYER_SIZE / 2 - 2, 8, 4);
        ctx.fillRect(-PLAYER_SIZE - 5, PLAYER_SIZE / 2 - 2, 8, 4);

        // Driver head (top-down view)
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = this.name === 'Mario' ? '#f00' : 
                        this.name === 'Luigi' ? '#090' : 
                        this.name === 'Wario' ? '#666' : '#333';
        ctx.beginPath();
        ctx.arc(0, -4, 5, 0, Math.PI * 2);
        ctx.fill();

        // Items indicator
        if (this.items.length > 0) {
            const item = this.items[0];
            ctx.fillStyle = ITEMS[item].color;
            ctx.fillRect(PLAYER_SIZE + 4, -3, 6, 6);
        }

        ctx.restore();
    }
}

// ========== INITIALIZE TRACK SEGMENTS ==========
function buildTrackSegments() {
    gameState.trackSegments = [];
    for (let i = 0; i < TRACK_POINTS.length; i++) {
        const p0 = TRACK_POINTS[i];
        const p1 = TRACK_POINTS[(i + 1) % TRACK_POINTS.length];
        const dx = p1.x - p0.x;
        const dy = p1.y - p0.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        gameState.trackSegments.push({
            x: p0.x, y: p0.y,
            dx, dy, len, angle: Math.atan2(dy, dx)
        });
    }

    // Place items on track
    gameState.itemPositions = [];
    for (let i = 1; i < TRACK_POINTS.length * 2; i++) {
        if (i % 3 === 0 || i % 5 === 0) {
            const point = gameState.getPointOnTrack(i);
            const types = ['banana', 'shell', 'mushroom', 'star'];
            const type = types[Math.floor(Math.random() * types.length)];
            gameState.itemsOnTrack.push({
                x: point.x, y: point.y,
                type, collected: false
            });
        }
    }
}

// ========== DRAW TRACK ==========
function drawTrack(ctx) {
    // Draw grass background
    ctx.fillStyle = '#2e8340';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw track road
    ctx.strokeStyle = '#5a5a6a';
    ctx.lineWidth = TRACK_WIDTH;
    ctx.beginPath();
    ctx.moveTo(TRACK_POINTS[0].x, TRACK_POINTS[0].y);
    for (let i = 1; i < TRACK_POINTS.length; i++) {
        ctx.lineTo(TRACK_POINTS[i].x, TRACK_POINTS[i].y);
    }
    ctx.closePath();
    ctx.stroke();

    // Track center line (dashed)
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.moveTo(TRACK_POINTS[0].x, TRACK_POINTS[0].y);
    for (let i = 1; i < TRACK_POINTS.length; i++) {
        ctx.lineTo(TRACK_POINTS[i].x, TRACK_POINTS[i].y);
    }
    ctx.closePath();
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw finish line
    const p0 = TRACK_POINTS[0];
    const seg = gameState.trackSegments[0];
    ctx.save();
    ctx.translate(p0.x, p0.y);
    ctx.rotate(seg.angle + Math.PI / 2);
    ctx.fillStyle = '#fff';
    for (let i = -3; i <= 3; i++) {
        for (let j = 0; j < 4; j++) {
            const checkColor = (i + j) % 2 === 0 ? '#000' : '#fff';
            ctx.fillStyle = checkColor;
            ctx.fillRect(i * 15, j * 10 - 20, 15, 10);
        }
    }
    ctx.restore();

    // Draw items
    gameState.itemsOnTrack.forEach(item => {
        if (!item.collected) {
            const info = ITEMS[item.type];
            ctx.fillStyle = info.color;
            ctx.beginPath();
            ctx.arc(item.x, item.y, 8, 0, Math.PI * 2);
            ctx.fill();

            // Icon text
            ctx.fillStyle = '#000';
            ctx.font = '12px Arial';
            ctx.fillText(info.icon, item.x - 6, item.y + 4);
        }
    });
}

// ========== DRAW MINIMAP ==========
function drawMinimap() {
    miniCtx.fillStyle = '#333';
    miniCtx.fillRect(0, 0, miniCanvas.width, miniCanvas.height);

    // Scale track to minimap
    const scale = 180 / 600;
    miniCtx.save();
    miniCtx.translate(100, 100);
    miniCtx.scale(scale, scale);

    // Track
    miniCtx.strokeStyle = '#aaa';
    miniCtx.lineWidth = TRACK_WIDTH / scale;
    miniCtx.beginPath();
    miniCtx.moveTo(TRACK_POINTS[0].x, TRACK_POINTS[0].y);
    for (let i = 1; i < TRACK_POINTS.length; i++) {
        miniCtx.lineTo(TRACK_POINTS[i].x, TRACK_POINTS[i].y);
    }
    miniCtx.closePath();
    miniCtx.stroke();

    // Karts on minimap
    const allKarts = [gameState.playerKart, ...gameState.aiKarts];
    allKarts.forEach(kart => {
        miniCtx.fillStyle = kart.color;
        miniCtx.beginPath();
        miniCtx.arc(kart.position.x, kart.position.y, 3 / scale, 0, Math.PI * 2);
        miniCtx.fill();
    });

    miniCtx.restore();
}

// ========== DRAW PARTICLES ==========
function drawParticles(ctx) {
    gameState.particles.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
        ctx.fill();
        p.life--;
    });
    gameState.particles = gameState.particles.filter(p => p.life > 0);
}

// ========== DRAW PROJECTILES ==========
function drawProjectiles(ctx) {
    gameState.projectiles.forEach(p => {
        if (p.type === 'shell') {
            ctx.fillStyle = '#c6c';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 8, 0, Math.PI * 2);
            ctx.fill();
        } else if (p.type === 'banana') {
            ctx.fillStyle = '#fdd';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
            ctx.fill();
        }
    });
}

// ========== PLAYER MOVEMENT ==========
function handlePlayerMovement() {
    if (!gameState.playerKart || gameState.finished) return;

    const kart = gameState.playerKart;
    const currentPoint = kart.getPointOnTrack(kart.trackIndex);

    // Forward/accelerate
    if (keys.down) {
        kart.speed += ACCELERATION;
    } else {
        kart.speed = Math.max(0.5, kart.speed - 0.02);
    }

    // Turn left/right (steer perpendicular to track direction)
    if (keys.left) {
        const segIdx = Math.floor(kart.trackIndex) % TRACK_POINTS.length;
        const seg = gameState.trackSegments[segIdx];
        kart.angle += TURN_RATE * Math.cos(seg.angle);
        // Shift position left along track width
        const perpX = Math.cos(seg.angle + Math.PI / 2);
        const perpY = Math.sin(seg.angle + Math.PI / 2);
        currentPoint.x += perpX * 5;
        currentPoint.y += perpY * 5;
    }
    if (keys.right) {
        const segIdx = Math.floor(kart.trackIndex) % TRACK_POINTS.length;
        const seg = gameState.trackSegments[segIdx];
        kart.angle -= TURN_RATE * Math.cos(seg.angle);
        const perpX = Math.cos(seg.angle - Math.PI / 2);
        const perpY = Math.sin(seg.angle - Math.PI / 2);
        currentPoint.x += perpX * 5;
        currentPoint.y += perpY * 5;
    }

    // Keep on track (push back)
    const distanceFromCenter = Math.sqrt(
        (currentPoint.x - TRACK_POINTS[0].x) ** 2 + 
        (currentPoint.y - TRACK_POINTS[0].y) ** 2
    );
    // Simple track boundary enforcement
    kart.position.x = currentPoint.x;
    kart.position.y = currentPoint.y;

    // Cap speed
    kart.speed = Math.min(kart.speed, MAX_SPEED + (kart.boostTimer > 0 ? 2.5 : 0));

    // Pick up items
    gameState.itemsOnTrack.forEach(item => {
        if (!item.collected) {
            const dist = Math.hypot(item.x - kart.position.x, item.y - kart.position.y);
            if (dist < 15) {
                item.collected = true;
                kart.items.push(item.type);
                spawnParticles(item.x, item.y, '#fff', 8);
                updateHUD();
            }
        }
    });

    // Use items
    if (keys.space && kart.items.length > 0) {
        const type = kart.items.shift();
        useItem(kart, type);
        updateHUD();
    }

    kart.moveForwards();
}

// ========== AI KARTS ==========
function updateAI() {
    gameState.aiKarts.forEach(ai => {
        // Simple AI: follow track with varying speed and occasional overtaking
        const currentTrackPoint = ai.getPointOnTrack(ai.trackIndex);

        // Random speed variation
        if (Math.random() < 0.02) {
            ai.speed = Math.random() * MAX_SPEED;
        }

        // Occasionally boost
        if (ai.boostTimer === 0 && Math.random() < 0.05) {
            ai.boostTimer = 30;
        }

        // Move forward
        const speed = ai.boostTimer > 0 ? MAX_SPEED * 1.5 : Math.min(ai.speed, MAX_SPEED);
        ai.moveForwards();

        // Pick items randomly
        gameState.itemsOnTrack.forEach(item => {
            if (!item.collected) {
                const dist = Math.hypot(item.x - ai.position.x, item.y - ai.position.y);
                if (dist < 15 && Math.random() < 0.3) {
                    item.collected = true;
                    ai.items.push(item.type);
                    if (Math.random() < 0.5 && ai.items.length > 0) {
                        useItem(ai, ai.items[0]);
                        ai.items.shift();
                    }
                }
            }
        });

        // Spawn shell occasionally
        if (ai.boostTimer > 10 && Math.random() < 0.05) {
            spawnProjectile(ai.position.x, ai.position.y, ai.angle, 'shell');
        }
    });
}

// ========== ITEM USAGE ==========
function useItem(kart, type) {
    const info = ITEMS[type];

    if (type === 'mushroom') {
        kart.boostTimer = 60;
        spawnParticles(kart.position.x, kart.position.y, '#ff6600', 12);
    } else if (type === 'star') {
        kart.invincibleTimer = 120;
        spawnParticles(kart.position.x, kart.position.y, '#ffd700', 15);
    } else if (type === 'shell') {
        // Launch forward shell
        spawnProjectile(kart.position.x, kart.position.y, kart.angle, 'shell');
    } else if (type === 'banana') {
        // Drop banana behind
        spawnProjectile(
            kart.position.x - Math.cos(kart.angle) * 20,
            kart.position.y - Math.sin(kart.angle) * 20,
            0, 'banana'
        );
    }

