}

// ========== COLLISIONS ==========
function checkCollisions() {
    const allKarts = [gameState.playerKart, ...gameState.aiKarts];

    // Projectile vs kart collisions
    gameState.projectiles.forEach(proj => {
        allKarts.forEach(kart => {
            if (kart.invincibleTimer > 0) return;
            const dist = Math.hypot(proj.x - kart.position.x, proj.y - kart.position.y);
