                } else if (proj.type === 'banana') {
                    kart.spinTimer = 30;
                    spawnParticles(proj.x, proj.y, '#fdd', 8);
                    gameState.projectiles = gameState.projectiles.filter(p => p !== proj);
                }
            }
        });

        // Move projectile
        if (proj.type === 'shell') {
            proj.x += Math.cos(proj.angle) * MAX_SPEED;
            proj.y += Math.sin(proj.angle) * MAX_SPEED;
        }
    });

    // Kart vs kart collisions
    for (let i = 0; i < allKarts.length; i++) {
        for (let j = i + 1; j < allKarts.length; j++) {
            const dist = Math.hypot(
                allKarts[i].position.x - allKarts[j].position.x,
                allKarts[i].position.y - allKarts[j].position.y
            );
            if (dist < 15 && allKarts[i].invincibleTimer === 0 && allKarts[j].invincibleTimer === 0) {
                // Push apart and spin one
                const pushAngle = Math.atan2(
                    allKarts[j].position.y - allKarts[i].position.y,
                    allKarts[j].position.x - allKarts[i].position.x
                );
                allKarts[i].spinTimer = 30;
                allKarts[j].spinTimer = 20;

                const pushX = Math.cos(pushAngle) * 10;
                const pushY = Math.sin(pushAngle) * 10;
                allKarts[i].position.x -= pushX;
                allKarts[i].position.y -= pushY;
                allKarts[j].position.x += pushX;
                allKarts[j].position.y += pushY;

                spawnParticles(
                    (allKarts[i].position.x + allKarts[j].position.x) / 2,
                    (allKarts[i].position.y + allKarts[j].position.y) / 2,
                    '#ff0', 6
                );
            }
        }
    }
}

// ========== PARTICLES ==========
function spawnParticles(x, y, color, count) {
    for (let i = 0; i < count; i++) {
        gameState.particles.push({
            x: x + Math.random() * 20 - 10,
            y: y + Math.random() * 20 - 10,
            color,
            radius: Math.random() * 4 + 1,
            life: Math.random() * 20 + 10
        });
    }
}

function spawnProjectile(x, y, angle, type) {
    gameState.projectiles.push({ x, y, angle, type, life: 100 });
}

// ========== RANKING ==========
function updateRanking() {
    const allKarts = [gameState.playerKart, ...gameState.aiKarts];

    // Sort by lap then track progress
    allKarts.sort((a, b) => {
        if (a.lap !== b.lap) return a.lap - b.lap;
        return a.trackIndex - b.trackIndex;
    });

    const playerRank = allKarts.findIndex(k => k.id === 'player') + 1;

    // Determine position based on track progress (simple ranking)
    let rank = 1;
    for (let i = 0; i < allKarts.length; i++) {
        if (allKarts[i].id === 'player') {
            document.getElementById('position-display').textContent = `Position: ${rank}th`;
        }
        rank++;
    }

    document.getElementById('lap-display').textContent = `Lap: ${gameState.currentLap + 1} / ${TOTAL_LAPS}`;

    // Check finish
    if (gameState.playerKart && gameState.playerKart.lap >= TOTAL_LAPS) {
        gameState.finished = true;
        showMessage(`🏆 You finished in ${rank}th place! Time: ${Math.floor(gameState.raceTime)}s`);
    }

    updateHUD();
}

// ========== HUD UPDATE ==========
function updateHUD() {
    if (!gameState.playerKart) return;
    document.getElementById('speed-display').textContent = `Speed: ${Math.floor(gameState.playerKart.speed * 20)} km/h`;

    const itemStr = gameState.playerKart.items.length > 0 
        ? `${ITEMS[gameState.playerKart.items[0]].icon} - ${gameState.playerKart.items[0]}` 
        : 'None';
    document.getElementById('items-display').textContent = `Items: ${itemStr}`;

    updateRanking();
}

// ========== MESSAGE DISPLAY ==========
function showMessage(text) {
    const overlay = document.getElementById('message-overlay');
    overlay.textContent = text;
    overlay.style.display = 'block';
}

// ========== MAIN GAME LOOP ==========
let lastTime = 0;

function gameLoop(timestamp) {
    if (gameState.finished) return;

    const dt = timestamp - lastTime;
    lastTime = timestamp;
    gameState.raceTime += dt / 1000;

    // Clear canvas
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawTrack(ctx);

    handlePlayerMovement();
    updateAI();
    checkCollisions();

    // Draw karts
    gameState.playerKart.draw(ctx);
    gameState.aiKarts.forEach(ai => ai.draw(ctx));

    drawProjectiles(ctx);
    drawParticles(ctx);
    drawMinimap();

    requestAnimationFrame(gameLoop);
}

// ========== KEY HANDLING ==========
const keys = { up: false, down: false, left: false, right: false, space: false };

document.addEventListener('keydown', (e) => {
    switch(e.key) {
        case 'ArrowUp': keys.up = true; break;
        case 'ArrowDown': keys.down = true; break;
        case 'ArrowLeft': keys.left = true; break;
        case 'ArrowRight': keys.right = true; break;
        case ' ': keys.space = true; e.preventDefault(); break;
    }
});

document.addEventListener('keyup', (e) => {
    switch(e.key) {
        case 'ArrowUp': keys.up = false; break;
        case 'ArrowDown': keys.down = false; break;
        case 'ArrowLeft': keys.left = false; break;
        case 'ArrowRight': keys.right = false; break;
        case ' ': keys.space = false; break;
    }
});

// ========== START GAME ==========
function initGame() {
    gameState.playerKart = new Kart('player', '#f00', 'Mario');
    gameState.aiKarts = [
        new Kart('ai1', '#090', 'Luigi'),
        new Kart('ai2', '#36c', 'Peach'),
        new Kart('ai3', '#666', 'Wario')
    ];

    buildTrackSegments();

    showMessage("Press Arrow Keys to Race! 🏁");

    setTimeout(() => {
        document.getElementById('message-overlay').style.display = 'none';
        gameState.gameStarted = true;
        requestAnimationFrame(gameLoop);
    }, 1500);

    updateHUD();
}

initGame();
```

### How to Play:
- **Arrow Up**: Accelerate
- **Arrow Down**: Slow down / brake
- **Arrow Left/Right**: Steer on the track
- **Spacebar**: Use item (shell throws forward, banana drops behind, mushroom boosts speed, star makes you invincible)

### Features:
- **4-player racing** (you + 3 AI opponents)
- **Track with finish line** and lap system (3 laps)
- **Item pickups** scattered around the track
- **Shell throws** hit other karts causing spin-outs
- **Bananas** dropped behind you to trip others
- **Mushroom boost** for speed burst
- **Star power** for invincibility (immune to shells/spins)
- **Kart-to-kart collisions** push apart and cause spinning
- **Minimap** showing all kart positions
- **Real-time HUD** with position, lap, speed, and items

