### `script.js`
```javascript
// ==================== CONFIGURATION ====================
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const NUM_LAPS = 3;
const NUM_AI = 4;
const TRACK_RADIUS_X = 350;
const TRACK_RADIUS_Y = 250;
const TRACK_CENTER_X = CANVAS_WIDTH / 2;
const TRACK_CENTER_Y = CANVAS_HEIGHT / 2;
const CAR_SIZE = 16;

// ==================== GAME STATE ====================
let gameState = {
    running: false,
    player: null,
    aiCars: [],
    itemsOnTrack: [],
    thrownShells: [],
    coins: [],
    currentLap: 1,
    totalLaps: NUM_LAPS,
    startTime: 0,
    finishPositions: [],
};

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;

// ==================== TRACK GENERATION ====================
function generateTrackPoints() {
    const points = [];
    for (let i = 0; i < 360; i++) {
        const rad = (i * Math.PI) / 180;
        const x = TRACK_CENTER_X + TRACK_RADIUS_X * Math.cos(rad);
        const y = TRACK_CENTER_Y + TRACK_RADIUS_Y * Math.sin(rad);
        points.push({ x, y });
    }
    return points;
}

const trackPoints = generateTrackPoints();

function getTrackPoint(angle) {
    const idx = Math.floor(angle % 360) % trackPoints.length;
    return trackPoints[idx];
}

// ==================== CAR CLASS ====================
class Car {
    constructor(color, name, isPlayer = false, startAngle = 270) {
        this.color = color;
        this.name = name;
        this.isPlayer = isPlayer;
        this.angle = startAngle;
        this.speed = 0;
        this.maxSpeed = isPlayer ? 18 : 14 + Math.random() * 3;
        this.acceleration = 0.3;
        this.braking = 0.5;
        this.positionX = TRACK_CENTER_X;
        this.positionY = TRACK_CENTER_Y + 50;
        this.angleDeg = startAngle;
        this.lap = 1;
        this.totalProgress = 0;
        this.item = null;
        this.coins = 0;
        this.boostTimer = 0;
        this.isFinished = false;
        this.finishTime = 0;
    }

    move() {
        if (this.isFinished) return;

        let spd = this.speed;
        if (this.boostTimer > 0) {
            spd = this.maxSpeed * 1.5;
            this.boostTimer--;
        }

        const dirX = Math.cos(this.angleDeg * Math.PI / 180);
        const dirY = Math.sin(this.angleDeg * Math.PI / 180);

        let newX = this.positionX + dirX * spd;
        let newY = this.positionY + dirY * spd;

        // Keep car on track
        const dx = newX - TRACK_CENTER_X;
        const dy = newY - TRACK_CENTER_Y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const maxR = Math.max(TRACK_RADIUS_X, TRACK_RADIUS_Y) + 20;

        if (dist > maxR) {
            const nx = dx / dist;
            const ny = dy / dist;
            newX = TRACK_CENTER_X + nx * Math.min(dist, maxR);
            newY = TRACK_CENTER_Y + ny * Math.min(dist, maxR);
            // Adjust angle toward center direction on track
            const trackPt = getTrackPoint(this.angleDeg);
            const dx2 = trackPt.x - TRACK_CENTER_X;
            const dy2 = trackPt.y - TRACK_CENTER_Y;
            const d2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);
            this.angleDeg += Math.atan2(dy, dx) - Math.atan2(dy2, dx2) * 0.1;
        }

        // Check if near track edge and align to track direction
        const angleRad = (this.angleDeg * Math.PI) / 180;
        const trackPtOnAngle = getTrackPoint(this.angleDeg);
        const tdx = trackPtOnAngle.x - TRACK_CENTER_X;
        const tdy = trackPtOnAngle.y - TRACK_CENTER_Y;
        const tDist = Math.sqrt(tdx * tdx + tdy * tdy);

        if (tDist < TRACK_RADIUS_X - 30 || tDist > TRACK_RADIUS_X + 60) {
            // Pull back toward track center and align angle
            const pullX = TRACK_CENTER_X + (tdx / tDist) * TRACK_RADIUS_X;
            const pullY = TRACK_CENTER_Y + (tdy / tDist) * TRACK_RADIUS_Y;
            newX += (pullX - newX) * 0.5;
            newY += (pullY - newY) * 0.5;
        }

        this.positionX = newX;
        this.positionY = newY;

        // Track lap progress by angle
        let currentAngle = Math.atan2(this.positionY - TRACK_CENTER_Y, this.positionX - TRACK_CENTER_X);
        if (currentAngle < 0) currentAngle += 360;
        this.angleDeg = currentAngle;

        const prevProgress = this.totalProgress;
        // Normalize angle to track lap progress
        let normalizedAngle = this.angleDeg;
        if (normalizedAngle > 359) normalizedAngle -= 360;
        if (normalizedAngle < 0) normalizedAngle += 360;

        if (prevProgress > 350 && normalizedAngle < 10) {
            this.lap++;
        } else {
            this.totalProgress = normalizedAngle;
        }

        if (this.lap > this.totalLaps && !this.isFinished) {
            this.isFinished = true;
            this.finishTime = Date.now() - gameState.startTime;
        }
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.positionX, this.positionY);
        ctx.rotate(this.angleDeg * Math.PI / 180);

        // Car body
        ctx.fillStyle = this.color;
        ctx.fillRect(-CAR_SIZE / 2, -CAR_SIZE / 4, CAR_SIZE, CAR_SIZE / 2);

        // Wheels
        ctx.fillStyle = '#333';
        ctx.fillRect(-CAR_SIZE / 2 - 1, -CAR_SIZE / 2 - 1, 3, 4);
        ctx.fillRect(CAR_SIZE / 2 - 2, -CAR_SIZE / 2 - 1, 3, 4);
        ctx.fillRect(-CAR_SIZE / 2 - 1, CAR_SIZE / 4 - 3, 3, 4);
        ctx.fillRect(CAR_SIZE / 2 - 2, CAR_SIZE / 4 - 3, 3, 4);

        // Racing stripe
        ctx.fillStyle = '#fff';
        ctx.fillRect(-CAR_SIZE / 2 + 1, -CAR_SIZE / 4, CAR_SIZE - 2, CAR_SIZE / 6);

        // Star if boosted
        if (this.boostTimer > 0) {
            ctx.fillStyle = '#ffd700';
            ctx.beginPath();
            ctx.arc(0, 0, 5, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.restore();
    }
}

// ==================== ITEM TYPES ====================
const ITEM_TYPES = ['blueShell', 'greenShell', 'star', 'coin', 'banana'];
const ITEM_COLORS = {
    blueShell: '#0066cc',
    greenShell: '#00aa00',
    star: '#ffd700',
    coin: '#ffd243',
    banana: '#ffcc00'
};

function spawnItems() {
    gameState.itemsOnTrack = [];
    for (let i = 0; i < 15; i++) {
        const angle = Math.random() * 360;
        const pt = getTrackPoint(angle);
        const type = ITEM_TYPES[Math.floor(Math.random() * ITEM_TYPES.length)];
        gameState.itemsOnTrack.push({
            x: pt.x,
            y: pt.y,
            type,
            collected: false
        });
    }
}

function spawnCoins() {
    gameState.coins = [];
    for (let i = 0; i < 20; i++) {
        const angle = Math.random() * 360;
        const pt = getTrackPoint(angle);
        // Slightly off track for variety
        const offset = Math.random() * 40 - 20;
        const rad = (angle * Math.PI) / 180;
        gameState.coins.push({
            x: TRACK_CENTER_X + TRACK_RADIUS_X * Math.cos(rad) + Math.cos(rad + Math.PI/2) * offset,
            y: TRACK_CENTER_Y + TRACK_RADIUS_Y * Math.sin(rad) + Math.sin(rad + Math.PI/2) * offset,
            collected: false
        });
    }
}

// ==================== DRAW TRACK ====================
function drawTrack(ctx) {
    // Grass background
    ctx.fillStyle = '#3a5a3a';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Track surface (oval)
    ctx.beginPath();
    ctx.ellipse(TRACK_CENTER_X, TRACK_CENTER_Y, TRACK_RADIUS_X + 20, TRACK_RADIUS_Y + 20, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#7a7a7a';
    ctx.fill();

    // Inner track line (dashed)
    ctx.beginPath();
    ctx.ellipse(TRACK_CENTER_X, TRACK_CENTER_Y, TRACK_RADIUS_X, TRACK_RADIUS_Y, 0, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 3;
    ctx.setLineDash([15, 15]);
    ctx.stroke();
    ctx.setLineDash([]);

    // Outer track line
    ctx.beginPath();
    ctx.ellipse(TRACK_CENTER_X, TRACK_CENTER_Y, TRACK_RADIUS_X + 20, TRACK_RADIUS_Y + 20, 0, 0, Math.PI * 2);
    ctx.strokeStyle = '#ccc';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Grass border
    ctx.fillStyle = '#3a5a3a';
    ctx.beginPath();
    ctx.ellipse(TRACK_CENTER_X, TRACK_CENTER_Y, TRACK_RADIUS_X + 40, TRACK_RADIUS_Y + 40, 0, 0, Math.PI * 2);
    ctx.fill();

    // Checkered start/finish line at bottom
    const startY = TRACK_CENTER_Y + TRACK_RADIUS_Y + 20;
    for (let i = -10; i <= 10; i++) {
        const checkerX = TRACK_CENTER_X + i * 10;
        ctx.fillStyle = i % 2 === 0 ? '#000' : '#fff';
        ctx.fillRect(checkerX, startY - 15, 10, 30);
    }

    // Start arrow indicator
    ctx.fillStyle = '#ff6b35';
    ctx.font = '18px sans-serif';
    ctx.fillText('START', TRACK_CENTER_X, startY - 25);
}

// ==================== DRAW ITEMS & COINS ====================
function drawItems(ctx) {
    gameState.itemsOnTrack.forEach(item => {
        if (item.collected) return;
        ctx.fillStyle = ITEM_COLORS[item.type];
        ctx.beginPath();
        ctx.arc(item.x, item.y, 8, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.stroke();

        // Icon
        ctx.fillStyle = '#fff';
        ctx.font = '8px sans-serif';
        ctx.textAlign = 'center';
        let icon = '';
        if (item.type === 'blueShell') icon = '🦞';
        else if (item.type === 'greenShell') icon = '⚠️';
        else if (item.type === 'star') icon = '⭐';
        else if (item.type === 'banana') icon = '🍌';
        ctx.fillText(icon, item.x, item.y + 3);
    });

    gameState.coins.forEach(coin => {
        if (coin.collected) return;
        ctx.fillStyle = '#ffd243';
        ctx.beginPath();
        ctx.arc(coin.x, coin.y, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#ff8c00';
        ctx.lineWidth = 1;
        ctx.stroke();
    });
}

// ==================== DRAW THROWN SHELLS ====================
function drawShells(ctx) {
    gameState.thrownShells.forEach(shell => {
        ctx.fillStyle = shell.type === 'blueShell' ? '#0066cc' : '#00aa00';
        ctx.beginPath();
        ctx.arc(shell.x, shell.y, 7, 0, Math.PI * 2);
        ctx.fill();

        // Shell curve detail
        ctx.strokeStyle = '#333';
        ctx.lineWidth = 1;
        ctx.stroke();
    });
}

// ==================== MINIMAP ====================
function drawMinimap() {
    const mmCanvas = document.getElementById('minimap');
    const mmCtx = mmCanvas.getContext('2d');
    mmCtx.fillStyle = '#fff';
    mmCtx.fillRect(0, 0, mmCanvas.width, mmCanvas.height);

    const scale = 0.15;
    const offsetX = (TRACK_CENTER_X - TRACK_RADIUS_X * scale - 30);
    const offsetY = (TRACK_CENTER_Y - TRACK_RADIUS_Y * scale - 25);

    // Draw track on minimap
    mmCtx.beginPath();
    mmCtx.ellipse(TRACK_CENTER_X, TRACK_CENTER_Y, TRACK_RADIUS_X * scale, TRACK_RADIUS_Y * scale, 0, 0, Math.PI * 2);
    mmCtx.fillStyle = '#888';
    mmCtx.fill();

    // Draw cars
    gameState.aiCars.forEach(car => {
        mmCtx.beginPath();
        mmCtx.arc(
            offsetX + car.positionX - TRACK_CENTER_X + offsetX,
            offsetY + car.positionY - TRACK_CENTER_Y + offsetY,
            2, 0, Math.PI * 2);
        mmCtx.fillStyle = car.color;
        mmCtx.fill();
    });

    // Player on minimap
    if (gameState.player) {
        mmCtx.beginPath();
        mmCtx.arc(
            offsetX + gameState.player.positionX - TRACK_CENTER_X + offsetX,
            offsetY + gameState.player.positionY - TRACK_CENTER_Y + offsetY,
            3, 0, Math.PI * 2);
        mmCtx.fillStyle = '#ff6b35';
        mmCtx.fill();
    }

    // Labels
    mmCtx.fillStyle = '#333';
    mmCtx.font = '10px sans-serif';
    mmCtx.fillText('🏁', TRACK_CENTER_X, TRACK_CENTER_Y + TRACK_RADIUS_Y * scale);
}

// ==================== HUD UPDATE ====================
function updateHUD() {
    if (!gameState.player) return;

    // Calculate position
    const allCars = [gameState.player, ...gameState.aiCars];
    allCars.sort((a, b) => {
        if (a.isFinished && !b.isFinished) return -1;
        if (!a.isFinished && b.isFinished) return 1;
        return b.lap - a.lap || b.totalProgress - a.totalProgress;
    });

    const playerPos = allCars.indexOf(gameState.player) + 1;
    const posText = playerPos === 1 ? '🏆' : playerPos === 2 ? '🥈' : playerPos === 3 ? '🥉' : playerPos;
    document.getElementById('position-display').textContent = `Position: ${playerPos}${posText}`;

    const spdKmh = Math.round(gameState.player.speed * 10);
    document.getElementById('speed-display').textContent = `Speed: ${spdKmh} km/h`;
    document.getElementById('lap-display').textContent = `Lap: ${gameState.currentLap} / ${gameState.totalLaps}`;

    let itemText = '📦 No Item';
    if (gameState.player.item) {
        const icons = { blueShell: '🦞 Blue Shell', greenShell: '⚠️ Green Shell', star: '⭐ Star', banana: '🍌 Banana' };
        itemText = icons[gameState.player.item] || gameState.player.item;
    }
    document.getElementById('item-display').textContent = itemText;

    document.getElementById('coin-display').textContent = `Coins: ${gameState.player.coins}`;

    drawMinimap();
}

// ==================== ITEM PICKUP ====================
function checkItemPickup(car) {
    gameState.itemsOnTrack.forEach(item => {
        if (item.collected) return;
        const dist = Math.sqrt((car.positionX - item.x) ** 2 + (car.positionY - item.y) ** 2);
        if (dist < 15) {
            item.collected = true;
            car.item = item.type;
        }
    });

    gameState.coins.forEach(coin => {
        if (coin.collected) return;
        const dist = Math.sqrt((car.positionX - coin.x) ** 2 + (car.positionY - coin.y) ** 2);
        if (dist < 15) {
            coin.collected = true;
            car.coins++;
        }
    });
}

// ==================== SHOOT ITEMS ====================
function shootItem(car) {
    if (!car.item) return;
    const type = car.item;
    car.item = null;

    const angleRad = (car.angleDeg * Math.PI) / 180;
    gameState.thrownShells.push({
        x: car.positionX + Math.cos(angleRad) * CAR_SIZE,
        y: car.positionY + Math.sin(angleRad) * CAR_SIZE,
        dx: Math.cos(angleRad) * 6,
        dy: Math.sin(angleRad) * 6,
        type,
        life: 120 // frames ~ 2 seconds
    });
}

// ==================== SHELL PHYSICS ====================
function updateShells() {
    gameState.thrownShells.forEach(shell => {
        shell.x += shell.dx;
        shell.y += shell.dy;
        shell.life--;

        // Check if hits any car
        const allCars = [gameState.player, ...gameState.aiCars];
        allCars.forEach(car => {
            const dist = Math.sqrt((car.positionX - shell.x) ** 2 + (car.positionY - shell.y) ** 2);
            if (dist < 12 && !car.isFinished) {
                if (shell.type === 'blueShell') {
                    car.speed = Math.max(car.speed * 0.5, 2); // Slow down
                } else if (shell.type === 'greenShell') {
                    // Bounce back - just remove for simplicity
                    car.speed *= 0.8;
                } else if (shell.type === 'banana') {
                    // No effect, just visual
                }
            }
        });

        // Remove expired shells
        if (shell.life <= 0 || shell.x < 0 || shell.x > CANVAS_WIDTH || shell.y < 0 || shell.y > CANVAS_HEIGHT) {
            shell.dead = true;
        }
    });
    gameState.thrownShells = gameState.thrownShells.filter(s => !s.dead);
}

// ==================== AI CONTROLLER ====================
function updateAI(car) {
    if (car.isFinished || car.boostTimer > 0) return;

    // AI follows track with slight variation
    const targetAngle = getTrackPoint((car.angleDeg + 5) % 360);
    const dx = targetAngle.x - TRACK_CENTER_X;
    const dy = targetAngle.y - TRACK_CENTER_Y;
    const targetRad = Math.atan2(dy, dx) * 180 / Math.PI;

    // Small steering adjustments
    let angleDiff = targetRad - car.angleDeg;
    if (angleDiff > 180) angleDiff -= 360;
    if (angleDiff < -180) angleDiff += 360;

    car.angleDeg += angleDiff * 0.15;

    // Speed control - AI accelerates and varies speed
    const timeSinceStart = Date.now() - gameState.startTime;
    const progressFraction = (car.totalProgress + (car.lap - 1) * 360) / (360 * car.totalLaps);

    if (progressFraction < 0.3) {
        // Accelerating
        car.speed += car.acceleration * 0.8;
    } else if (progressFraction > 0.7) {
        // Slowing down near finish
        car.speed -= car.braking * 0.5;
    } else {
        // Cruising at consistent speed with variation
        car.speed = car.maxSpeed + Math.sin(timeSinceStart / 1000) * 2;
    }

    car.speed = Math.min(car.speed, car.maxSpeed);
    car.speed = Math.max(car.speed, 3);

    // Occasionally pick up items
    if (car.item === null && Math.random() < 0.02) {
        gameState.itemsOnTrack.forEach(item => {
            if (!item.collected) {
                const dist = Math.sqrt((car.positionX - item.x) ** 2 + (car.positionY - item.y) ** 2);
                if (dist < 15) {
                    item.collected = true;
                    car.item = item.type;
                }
            }
        });
    }

    // Occasionally throw items
    if (car.item && Math.random() < 0.03) {
        const angleRad = (car.angleDeg * Math.PI) / 180;
        gameState.thrownShells.push({
            x: car.positionX + Math.cos(angleRad) * CAR_SIZE,
            y: car.positionY + Math.sin(angleRad) * CAR_SIZE,
            dx: Math.cos(angleRad) * 5,
            dy: Math.sin(angleRad) * 5,
            type: car.item,
            life: 100
        });
        car.item = null;
    }
}

// ==================== INPUT HANDLING ====================
const keys = {};
document.addEventListener('keydown', (e) => {
    keys[e.key] = true;
    if (!gameState.running) return;

    if (e.key === 'ArrowUp' || e.key === 'w') {
        gameState.player.speed += gameState.player.acceleration;
    } else if (e.key === 'ArrowDown' || e.key === 's') {
        gameState.player.speed -= gameState.player.braking;
    } else if (e.key === 'ArrowLeft' || e.key === 'a') {
        gameState.player.angleDeg -= 3;
    } else if (e.key === 'ArrowRight' || e.key === 'd') {
        gameState.player.angleDeg += 3;
    } else if (e.key === 'Shift') {
        gameState.player.boostTimer = 60; // ~1 second boost
    } else if (e.key === ' ') {
        shootItem(gameState.player);
    }

    keys[e.key] = true;
});

document.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

// ==================== MAIN GAME LOOP ====================
function gameLoop() {
    if (!gameState.running) return;

    // Player movement
    gameState.player.speed = Math.min(gameState.player.speed, gameState.player.maxSpeed);
    gameState.player.speed = Math.max(gameState.player.speed, 1);

    gameState.player.move();
    checkItemPickup(gameState.player);
    updateShells();

    // AI update
    gameState.aiCars.forEach(car => {
        updateAI(car);
        car.move();
        checkItemPickup(car);
    });

    // Draw everything
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    drawTrack(ctx);
    drawItems(ctx);
    drawShells(ctx);

    // Sort cars by position for drawing order
    const allCars = [gameState.player, ...gameState.aiCars];
    gameState.aiCars.forEach(car => car.draw(ctx));
    gameState.player.draw(ctx);

    updateHUD();

    // Check if player finished
    if (gameState.player.isFinished) {
        finishRace();
        return;
    }

    requestAnimationFrame(gameLoop);
}

// ==================== FINISH RACE ====================
function finishRace() {
    gameState.running = false;

    const allCars = [gameState.player, ...gameState.aiCars];
    allCars.sort((a, b) => a.finishTime - b.finishTime);

    document.getElementById('finish-screen').style.display = 'block';

    const playerRank = allCars.indexOf(gameState.player) + 1;
    let msg = `You finished ${playerRank}${['st','nd','rd'][playerRank-1] === undefined ? 'th' : ''}!`;
    if (playerRank === 1) msg += ' 🏆';
    else if (playerRank === 2) msg += ' 🥈';
    else if (playerRank === 3) msg += ' 🥉';

    document.getElementById('finish-message').textContent = msg;
}

// ==================== START / RESTART ====================
function startRace() {
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('finish-screen').style.display = 'none';

    gameState.player = new Car('#ff6b35', 'Mario', true, 270);
    gameState.player.positionX = TRACK_CENTER_X;
    gameState.player.positionY = TRACK_CENTER_Y + TRACK_RADIUS_Y + 10;
    gameState.player.angleDeg = 90; // Facing right along the track

    const aiColors = ['#ff0000', '#0066cc', '#33aa33', '#cc00cc'];
    const aiNames = ['Luigi', 'Toad', 'Peach', 'Bowser'];
    gameState.aiCars = [];

    for (let i = 0; i < NUM_AI; i++) {
        const car = new Car(aiColors[i], aiNames[i], false, 265 + i * 10);
        car.positionX = TRACK_CENTER_X;
        car.positionY = TRACK_CENTER_Y + TRACK_RADIUS_Y + 10 + (i - 1) * 20;
        car.angleDeg = 90;
        gameState.aiCars.push(car);
    }

    spawnItems();
    spawnCoins();
    gameState.startTime = Date.now();
    gameState.running = true;
    gameLoop();
}

document.getElementById('start-btn').addEventListener('click', startRace);
document.getElementById('restart-btn').addEventListener('click', () => {
    document.getElementById('finish-screen').style.display = 'none';
    startRace();
});

// Initial HUD display
updateHUD();
```

## Features:
- **Top-down oval track** with grass, racing stripes, and start/finish line
- **Player car** controlled by Arrow Keys (Up/Down for accel/brake, Left/Right for steering)
- **4 AI opponents** (Luigi, Toad, Peach, Bowser) with varied speeds
- **5 item types**: Blue Shell 🦞, Green Shell ⚠️, Star ⭐, Banana 🍌, Coins
- **Throw items** with Spacebar, boost with Shift
- **Lap tracking** (3 laps), position display, speed readout
- **Mini-map** showing all racers
- **Finish screen** with ranking

