### 3. `script.js`
This file contains the game logic, physics, rendering, and AI behavior.

```javascript
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const width = canvas.width;
const height = canvas.height;

// Game State
let raceFinished = false;
let lapCount = 0;
const totalLaps = 3;

// Track Definition (Simple Oval)
const trackCenter = { x: width / 2, y: height / 2 };
const trackRadiusX = 300;
const trackRadiusY = 150;

// Kart Class
class Kart {
    constructor(name, color, isPlayer = false) {
        this.name = name;
        this.color = color;
        this.isPlayer = isPlayer;

        // Position (Start at bottom of the oval)
        this.x = trackCenter.x;
        this.y = trackCenter.y + trackRadiusY;

        // Velocity
        this.vx = 0;
        this.vy = 0;
        this.speed = 0;
        this.angle = -Math.PI / 2; // Facing Up

        // Item
        this.item = null;
        this.hasItem = false;
    }

    update() {
        if (raceFinished) return;

        // Physics & Movement
        this.x += this.vx;
        this.y += this.vy;

        // Check bounds to keep on track (Simple collision logic)
        // We calculate distance from center. If too far, push back.
        const dist = Math.sqrt((this.x - trackCenter.x)**2 + (this.y - trackCenter.y)**2);

        // If off-track, apply centripetal force to bring them back
        if (dist > trackRadiusX + 50 || dist < trackRadiusX - 100) {
             // Simplified track logic: Just reset angle and speed slightly if off-road
             this.speed *= 0.9; 
        }

        // AI Logic for CPU Karts
        if (!this.isPlayer) {
            this.followTrack();
        } else {
            this.playerInput();
        }

        // Check Lap Completion (Cross the finish line at top)
        // Finish line is roughly at y = trackCenter.y - trackRadiusY
        if (this.y < trackCenter.y - trackRadiusY && Math.abs(this.x - trackCenter.x) < 50) {
            lapCount++;
            this.y = trackCenter.y + trackRadiusY; // Reset position for next lap
            this.vx = 0; 
            this.vy = -this.speed; // Keep moving up
        }
    }

    playerInput() {
        if (keys['ArrowUp'] || keys['w']) {
            this.speed += 0.5;
        } else {
            this.speed -= 0.1; // Friction
        }

        if (this.speed > 8) this.speed = 8; // Max speed
        if (this.speed < 0) this.speed = 0;

        if (keys['ArrowLeft'] || keys['a']) {
            this.angle -= 0.05;
        }
        if (keys['ArrowRight'] || keys['d']) {
            this.angle += 0.05;
        }

        // Calculate velocity based on angle
        this.vx = Math.cos(this.angle) * this.speed;
        this.vy = Math.sin(this.angle) * this.speed;

        if (keys[' '] && this.hasItem) {
            this.useItem();
        }
    }

    followTrack() {
        // Simple AI: Aim towards the center of the track slightly ahead
        const targetX = trackCenter.x + Math.cos(this.angle) * 100;
        const targetY = trackCenter.y + Math.sin(this.angle) * 100;

        // Calculate angle to target
        let dx = targetX - this.x;
        let dy = targetY - this.y;
        let targetAngle = Math.atan2(dy, dx);

        // Smoothly turn towards target
        if (this.angle < targetAngle) this.angle += 0.1;
        else this.angle -= 0.1;

        // AI Speed varies randomly
        this.speed = 4 + Math.random() * 3; 

        this.vx = Math.cos(this.angle) * this.speed;
        this.vy = Math.sin(this.angle) * this.speed;
    }

    useItem() {
        if (this.item === 'banana') {
            // Drop banana behind
            this.itemsOnTrack.push({ x: this.x, y: this.y });
            this.hasItem = false;
            this.item = null;
        } else if (this.item === 'shell') {
            // Shoot shell forward
            this.projectiles.push({ 
                x: this.x, 
                y: this.y, 
                vx: Math.cos(this.angle) * 10, 
                vy: Math.sin(this.angle) * 10 
            });
            this.hasItem = false;
            this.item = null;
        }
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);

        // Draw Kart Body
        ctx.fillStyle = this.color;
        ctx.fillRect(-10, -10, 20, 20);

        // Draw Wheels
        ctx.fillStyle = '#333';
        ctx.fillRect(-15, -10, 5, 5);
        ctx.fillRect(10, -10, 5, 5);
        ctx.fillRect(-15, 5, 5, 5);
        ctx.fillRect(10, 5, 5, 5);

        // Draw Item Icon if holding
        if (this.hasItem) {
            ctx.fillStyle = this.item === 'banana' ? '#ffff00' : '#ff0000';
            ctx.beginPath();
            ctx.arc(0, -15, 5, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.restore();

        // Draw Name Label
        ctx.fillStyle = 'white';
        ctx.font = '10px Arial';
        ctx.fillText(this.name, this.x, this.y - 20);
    }
}

// Global Game Objects
let karts = [];
let keys = {};
let itemsOnTrack = []; // Bananas on ground
let projectiles = []; // Shells flying

// Initialize Game
function init() {
    karts = [
        new Kart("Mario", "#ff0000", true),
        new Kart("Luigi", "#00ff00", false),
        new Kart("Peach", "#ff00ff", false),
        new Kart("Bowser", "#ff8800", false)
    ];

    // Give items randomly
    karts.forEach(k => {
        if(Math.random() > 0.5) {
            k.item = 'banana';
            k.hasItem = true;
        } else {
            k.item = 'shell';
            k.hasItem = true;
        }
    });

    raceFinished = false;
    lapCount = 0;

    // Reset UI
    document.getElementById('position-display').innerText = "1st";
    document.getElementById('item-display').innerText = karts[0].hasItem ? karts[0].item : "None";
}

// Input Handling
window.addEventListener('keydown', (e) => keys[e.key] = true);
window.addEventListener('keyup', (e) => keys[e.key] = false);
document.getElementById('restart-btn').addEventListener('click', init);

// Main Game Loop
function gameLoop() {
    // Clear Canvas
    ctx.clearRect(0, 0, width, height);

    // Draw Track (Oval)
    ctx.beginPath();
