```javascript
// --- Configuration ---
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
canvas.width = 600;
canvas.height = 400;

// --- Game State ---
let lap = 1;
const totalLaps = 3;
let checkpoints = []; // Array of points to check for lap completion
let gameActive = true;

// --- Player Object ---
const player = {
    x: 300,
    y: 200,
    angle: -Math.PI / 2, // Facing Up
    speed: 0,
    maxSpeed: 8,
    acceleration: 0.15,
    friction: 0.96,
    turnRate: 0.04,
    color: '#ff0000' // Mario Red
};

// --- Track Definition (Simple Oval) ---
const trackWidth = 80;
const centerX = canvas.width / 2;
const centerY = canvas.height / 2;
const radiusX = 250;
const radiusY = 150;

// --- Input Handling ---
const keys = {};

document.addEventListener('keydown', (e) => {
    keys[e.code] = true;
});

document.addEventListener('keyup', (e) => {
    keys[e.code] = false;
});

// --- Helper: Check if point is inside the track oval ---
function isOnTrack(x, y) {
    // Ellipse equation: (x-h)^2/a^2 + (y-k)^2/b^2 <= 1
    const dx = x - centerX;
    const dy = y - centerY;
    const distSq = (dx * dx) / (radiusX * radiusX) + (dy * dy) / (radiusY * radiusY);

    // We want the player to be within the track width. 
    // The "Road" is roughly between radius 250 and radius 170 (approx).
    // Let's define a collision boundary slightly inside the outer edge.
    return distSq <= 0.9; // 0.9 allows some margin, 1.0 is exact edge
}

// --- Update Physics ---
function update() {
    if (!gameActive) return;

    // Acceleration (Up/Down keys)
    if (keys['ArrowUp']) {
        player.speed += player.acceleration;
    } else if (keys['ArrowDown']) {
        player.speed -= player.acceleration;
    }

    // Steering (Left/Right keys)
    // Only steer if moving
    if (player.speed > 0.1) {
        if (keys['ArrowLeft']) {
            player.angle -= player.turnRate;
        }
        if (keys['ArrowRight']) {
            player.angle += player.turnRate;
        }
    }

    // Boost/Drift (Spacebar)
    if (keys['Space'] && player.speed > 0) {
        player.speed += 0.5; // Temporary boost
    }

    // Apply Friction and Cap Speed
    player.speed *= player.friction;
    if (player.speed < 0) player.speed = 0;
    if (player.speed > player.maxSpeed) player.speed = player.maxSpeed;

    // Calculate new position based on angle and speed
    const dx = Math.cos(player.angle) * player.speed;
    const dy = Math.sin(player.angle) * player.speed;

    const nextX = player.x + dx;
    const nextY = player.y + dy;

    // Collision Check: If off track, slow down significantly and bounce back slightly
    if (!isOnTrack(nextX, nextY)) {
        player.speed *= 0.5; // Penalty for going off-road
        // Simple boundary push (very basic physics)
        const dx = player.x - centerX;
        const dy = player.y - centerY;
        const angleToCenter = Math.atan2(dy, dx);

        // Push back towards center slightly
        player.x -= Math.cos(angleToCenter) * 5;
        player.y -= Math.sin(angleToCenter) * 5;
    } else {
        player.x = nextX;
        player.y = nextY;
    }

    // Lap Logic (Check if passed top center line)
    if (player.y < centerY && Math.abs(player.x - centerX) < 10) {
        lap++;
        if (lap > totalLaps) {
            gameActive = false;
            alert("Race Complete! You won!");
        }
    }

    // Update UI
    document.getElementById('score-board').innerHTML = `
        <span>Lap: ${lap} / ${totalLaps}</span>
        <span>Speed: ${Math.floor(player.speed * 10)} km/h</span>
    `;
}

// --- Render Graphics ---
function draw() {
    // Clear Canvas
    ctx.fillStyle = '#4caf50'; // Grass background
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw Track (The Oval)
    ctx.strokeStyle = '#ccc'; // Road color
    ctx.lineWidth = trackWidth;
    ctx.beginPath();
    ctx.arc(centerX, centerY, radiusX, 0, Math.PI * 2); // Outer boundary logic is simplified here
    ctx.stroke();

    // Draw Track Lines (Start/Finish)
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(centerX - 10, centerY);
    ctx.lineTo(centerX + 10, centerY);
    ctx.stroke();

    // Draw Player (Car)
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(player.angle + Math.PI / 2); // Adjust rotation for drawing

    // Car Body
    ctx.fillStyle = player.color;
    ctx.fillRect(-10, -5, 20, 10);

    // Wheels
    ctx.fillStyle = '#000';
    ctx.fillRect(-8, -8, 4, 4); // Back Left
    ctx.fillRect(4, -8, 4, 4);  // Front Left (simplified)
    ctx.fillRect(-8, 4, 4, 4);  // Back Right
    ctx.fillRect(4, 4, 4, 4);   // Front Right

    ctx.restore();
}

// --- Game Loop ---
function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Start the game
gameLoop();
