### 3. game.js
This file contains the physics engine, rendering logic, track generation, and AI opponent.

```javascript
// --- Configuration ---
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const FPS = 60;

// --- Game State ---
let canvas = document.getElementById('gameCanvas');
let ctx = canvas.getContext('2d');

let player = {
    x: 400,
    y: 300,
    speed: 0,
    angle: 0, // Radians
    lap: 1,
    totalLaps: 3,
    item: null, // 'Mushroom' or 'Shell'
    color: '#ff4d4d', // Mario Red
    width: 20,
    height: 20
};

let opponent = {
    x: 400,
    y: 350,
    speed: 0,
    angle: Math.PI / 2,
    lap: 1,
    totalLaps: 3,
    color: '#4d4dff', // Blue (Luigi-ish)
    width: 20,
    height: 20
};

let track = [];
let checkpoints = [];
let itemsOnTrack = [];

// Input State
const keys = {};

// --- Initialization ---
function initGame() {
    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;

    generateTrack();
    spawnItems();

    // Start Loop
    requestAnimationFrame(gameLoop);
}

// --- Track Generation (Procedural Oval) ---
function generateTrack() {
    // We define a path using points. The track is an oval centered on the canvas.
    const centerX = CANVAS_WIDTH / 2;
    const centerY = CANVAS_HEIGHT / 2;
    const radiusX = 300;
    const radiusY = 150;

    // Create a smooth curve using sine/cosine
    for (let i = 0; i < 360; i++) {
        const angleRad = (i * Math.PI) / 180;
        const x = centerX + radiusX * Math.cos(angleRad);
        const y = centerY + radiusY * Math.sin(angleRad);
        track.push({ x, y });
    }

    // Define Checkpoints to detect laps
    checkpoints = [
        { x: centerX - 300, y: centerY }, // Left side
        { x: centerX, y: centerY - 150 }, // Top
        { x: centerX + 300, y: centerY }, // Right
        { x: centerX, y: centerY + 150 }  // Bottom
    ];
}

function spawnItems() {
    // Randomly place items on the track
    for (let i = 0; i < 5; i++) {
        const idx = Math.floor(Math.random() * track.length);
        itemsOnTrack.push({
            x: track[idx].x,
            y: track[idx].y,
            type: Math.random() > 0.5 ? 'Mushroom' : 'Shell',
            active: true
        });
    }
}

// --- Physics & Logic ---
function updatePlayer(dt) {
    // Controls
    if (keys['ArrowUp']) player.speed += 0.1;
    if (keys['ArrowDown']) player.speed -= 0.1;

    // Friction
    player.speed *= 0.98;

    // Steering
    if (keys['ArrowLeft']) player.angle -= 0.05;
    if (keys['ArrowRight']) player.angle += 0.05;

    // Move Player
    const dx = Math.cos(player.angle) * player.speed;
    const dy = Math.sin(player.angle) * player.speed;

    player.x += dx;
    player.y += dy;

    // Keep player within canvas bounds (soft wall)
    if (player.x < 0) player.x = 0;
    if (player.x > CANVAS_WIDTH) player.x = CANVAS_WIDTH;
    if (player.y < 0) player.y = 0;
    if (player.y > CANVAS_HEIGHT) player.y = CANVAS_HEIGHT;

    // Check Item Pickup
    itemsOnTrack.forEach(item => {
        if (item.active && Math.hypot(player.x - item.x, player.y - item.y) < 20) {
            player.item = item.type;
            item.active = false;
            updateHUD();
        }
    });

    // Use Item
    if (keys[' '] && player.item) {
        useItem(player.item);
        player.item = null;
        updateHUD();
    }

    // Lap Logic
    checkLapProgress();
}

function updateOpponent(dt) {
    // Simple AI: Follow the track points
    // Find the closest point on the track
    let closestDist = Infinity;
    let targetPoint = null;

    for (let p of track) {
        const dist = Math.hypot(opponent.x - p.x, opponent.y - p.y);
        if (dist < closestDist) {
            closestDist = dist;
            targetPoint = p;
        }
    }

    // Calculate angle to target
    const targetAngle = Math.atan2(targetPoint.y - opponent.y, targetPoint.x - opponent.x);

    // Smooth steering towards target
    if (targetAngle > opponent.angle) {
        opponent.angle += 0.1;
    } else {
        opponent.angle -= 0.1;
    }

    // Accelerate
    opponent.speed += 0.2;
    if (opponent.speed > 4) opponent.speed = 4; // Max speed cap

    const dx = Math.cos(opponent.angle) * opponent.speed;
    const dy = Math.sin(opponent.angle) * opponent.speed;

    opponent.x += dx;
    opponent.y += dy;

    // Check Lap
    checkLapProgressForOpponent();
}

function useItem(type) {
    if (type === 'Mushroom') {
        player.speed += 2; // Boost speed
    } else if (type === 'Shell') {
        // Throw shell forward
        // In a real game, this would be a projectile. 
        // Here we just boost speed for simplicity or hit the opponent.
        player.speed += 1.5;

        // Check collision with opponent
        const dist = Math.hypot(player.x - opponent.x, player.y - opponent.y);
        if (dist < 50) {
            opponent.speed = 0; // Stop opponent for a moment
            setTimeout(() => opponent.speed = 2, 1000);
        }
    }
}

function checkLapProgress() {
    // Check if player crossed specific checkpoints in order
    // Simplified: Just count distance from start point
    const startPt = track[0];
    const distToStart = Math.hypot(player.x - startPt.x, player.y - startPt.y);

    // If close to start and moving fast enough, increment lap
    if (distToStart < 20 && player.speed > 1) {
        player.lap++;
        if (player.lap > player.totalLaps) {
            endGame("You Won!");
        }
        updateHUD();
    }
}

function checkLapProgressForOpponent() {
    const startPt = track[0];
    const distToStart = Math.hypot(opponent.x - startPt.x, opponent.y - startPt.y);

    if (distToStart < 20 && opponent.speed > 1) {
        opponent.lap++;
        if (opponent.lap > opponent.totalLaps) {
            endGame("Opponent Won!");
        }
    }
}

// --- Rendering ---
function drawTrack() {
    ctx.fillStyle = '#333'; // Road color

    ctx.beginPath();
    ctx.lineWidth = 40; // Road width
    ctx.strokeStyle = '#555';

    for (let i = 0; i < track.length; i++) {
        if (i === 0) ctx.moveTo(track[i].x, track[i].y);
        else ctx.lineTo(track[i].x, track[i].y);
    }
    ctx.closePath();
    ctx.stroke();

    // Draw Start/Finish Line
    const start = track[0];
    ctx.beginPath();
    ctx.lineWidth = 5;
    ctx.strokeStyle = 'white';
    ctx.moveTo(start.x - 10, start.y);
    ctx.lineTo(start.x + 10, start.y);
    ctx.stroke();

    // Draw Items
    itemsOnTrack.forEach(item => {
        if (item.active) {
            ctx.fillStyle = item.type === 'Mushroom' ? '#fff' : '#ff4d4d';
            ctx.beginPath();
            ctx.arc(item.x, item.y, 10, 0, Math.PI * 2);
            ctx.fill();
        }
    });
}

function drawKart(kart) {
    ctx.save();
    ctx.translate(kart.x, kart.y);
    ctx.rotate(kart.angle);

    // Draw Body
    ctx.fillStyle = kart.color;
    ctx.fillRect(-10, -10, 20, 20);

    // Draw Wheels (visual approximation)
    ctx.fillStyle = '#000';
    ctx.fillRect(-15, -5, 5, 10);
    ctx.fillRect(10, -5, 5, 10);

    ctx.restore();
}

function updateHUD() {
    document.getElementById('lapDisplay').innerText = player.lap;
    document.getElementById('speedDisplay').innerText = Math.floor(player.speed * 20); // Fake km/h
    document.getElementById('itemDisplay').innerText = player.item || 'None';
}

// --- Main Loop ---
let lastTime = 0;

function gameLoop(timestamp) {
    const dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    // Clear Canvas
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Background (Grass)
    ctx.fillStyle = '#88cc88';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    drawTrack();

    updatePlayer(dt);
    updateOpponent(dt);

    drawKart(player);
    drawKart(opponent);

    requestAnimationFrame(gameLoop);
}

// --- Input Handling ---
window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
});

window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

function endGame(message) {
    document.getElementById('gameOver').classList.remove('hidden');
    document.querySelector('#gameOver h1').innerText = message;
}

function resetGame() {
    player.lap = 1;
    opponent.lap = 1;
    player.x = 400;
    player.y = 300;
    player.speed = 0;
    opponent.x = 400;
    opponent.y = 350;
    opponent.speed = 0;
    itemsOnTrack.forEach(i => i.active = true);

    document.getElementById('gameOver').classList.add('hidden');
    updateHUD();
}

// Start the game
initGame();
```

