    if (opponent.speed > 4) opponent.speed = 4; // Max speed cap

    const dx = Math.cos(opponent.angle) * opponent.speed;
    const dy = Math.sin(opponent.angle) * opponent.speed;

    opponent.x += dx;
    opponent.y += dy;

    // Check Lap
    checkLapProgressForOpponent();
}

function useItem(type) {
    if (type === 'Mushroom') {
        player.speed += 2; // Boost speed
    } else if (type === 'Shell') {
        // Throw shell forward
        // In a real game, this would be a projectile. 
        // Here we just boost speed for simplicity or hit the opponent.
        player.speed += 1.5;

        // Check collision with opponent
        const dist = Math.hypot(player.x - opponent.x, player.y - opponent.y);
        if (dist < 50) {
            opponent.speed = 0; // Stop opponent for a moment
            setTimeout(() => opponent.speed = 2, 1000);
        }
    }
}

function checkLapProgress() {
    // Check if player crossed specific checkpoints in order
    // Simplified: Just count distance from start point
    const startPt = track[0];
    const distToStart = Math.hypot(player.x - startPt.x, player.y - startPt.y);

    // If close to start and moving fast enough, increment lap
    if (distToStart < 20 && player.speed > 1) {
        player.lap++;
        if (player.lap > player.totalLaps) {
            endGame("You Won!");
        }
        updateHUD();
    }
}

function checkLapProgressForOpponent() {
    const startPt = track[0];
    const distToStart = Math.hypot(opponent.x - startPt.x, opponent.y - startPt.y);

    if (distToStart < 20 && opponent.speed > 1) {
        opponent.lap++;
        if (opponent.lap > opponent.totalLaps) {
            endGame("Opponent Won!");
        }
    }
}

// --- Rendering ---
function drawTrack() {
    ctx.fillStyle = '#333'; // Road color

    ctx.beginPath();
    ctx.lineWidth = 40; // Road width
    ctx.strokeStyle = '#555';

    for (let i = 0; i < track.length; i++) {
        if (i === 0) ctx.moveTo(track[i].x, track[i].y);
        else ctx.lineTo(track[i].x, track[i].y);
    }
    ctx.closePath();
    ctx.stroke();

    // Draw Start/Finish Line
    const start = track[0];
    ctx.beginPath();
    ctx.lineWidth = 5;
    ctx.strokeStyle = 'white';
    ctx.moveTo(start.x - 10, start.y);
    ctx.lineTo(start.x + 10, start.y);
    ctx.stroke();

    // Draw Items
    itemsOnTrack.forEach(item => {
        if (item.active) {
            ctx.fillStyle = item.type === 'Mushroom' ? '#fff' : '#ff4d4d';
            ctx.beginPath();
            ctx.arc(item.x, item.y, 10, 0, Math.PI * 2);
            ctx.fill();
        }
    });
}

function drawKart(kart) {
    ctx.save();
    ctx.translate(kart.x, kart.y);
    ctx.rotate(kart.angle);

    // Draw Body
    ctx.fillStyle = kart.color;
    ctx.fillRect(-10, -10, 20, 20);

    // Draw Wheels (visual approximation)
    ctx.fillStyle = '#000';
    ctx.fillRect(-15, -5, 5, 10);
    ctx.fillRect(10, -5, 5, 10);

    ctx.restore();
}

function updateHUD() {
    document.getElementById('lapDisplay').innerText = player.lap;
    document.getElementById('speedDisplay').innerText = Math.floor(player.speed * 20); // Fake km/h
    document.getElementById('itemDisplay').innerText = player.item || 'None';
}

// --- Main Loop ---
let lastTime = 0;

function gameLoop(timestamp) {
    const dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    // Clear Canvas
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Background (Grass)
    ctx.fillStyle = '#88cc88';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    drawTrack();

    updatePlayer(dt);
    updateOpponent(dt);

    drawKart(player);
    drawKart(opponent);

    requestAnimationFrame(gameLoop);
}

// --- Input Handling ---
window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
});

window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

function endGame(message) {
    document.getElementById('gameOver').classList.remove('hidden');
    document.querySelector('#gameOver h1').innerText = message;
}

function resetGame() {
    player.lap = 1;
    opponent.lap = 1;
    player.x = 400;
    player.y = 300;
    player.speed = 0;
    opponent.x = 400;
    opponent.y = 350;
    opponent.speed = 0;
    itemsOnTrack.forEach(i => i.active = true);

    document.getElementById('gameOver').classList.add('hidden');
    updateHUD();
}

// Start the game
initGame();
